def gen(rng):
    def fmt(a):
        return '%d\n%s' % (len(a), ' '.join(map(str, a)))
    tests = [fmt([5]), fmt([1, 1]), fmt([1, 2, 3]), fmt([3, 2, 1, 3, 2, 1]), fmt([0, 0, 0, 0]),
             fmt([-1, 5, 0, -1, 0, 5]), fmt([10**9, -10**9, 10**9, -10**9])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for r in (2, 5, 100):
            tests.append(fmt([rng.randint(-r, r) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 100) for _ in range(N)]))
    tests.append(fmt([7] * N))
    tests.append(fmt([rng.randint(-50000, 50000) for _ in range(N)]))
    return tests
